+  --color-background-muted: #f5f5f4;
+  --color-foreground: #1c1917;
+  --color-muted: #57534e;
+  --color-faint: #8b8b88;
+  --color-border: #e7e5e4;
+  --color-border-strong: #d6d3d1;
   --color-surface: #ffffff;
-  --color-surface-hover: #fafafa;
+  --color-surface-hover: #f5f5f4;
   --color-accent: #0070f3;
   --color-accent-muted: #3291ff;
-  --color-link: #171717;
+  --color-link: #1c1917;

   --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
   --ease-out-quad: cubic-bezier(0.25, 1, 0.5, 1);
+  --ease-bounce: cubic-bezier(0.2, -0.25, 0, 1.6);
 }

 .dark {
-  --color-background: #000000;
