.site-atmosphere {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  background: var(--color-background);
}

.site-atmosphere::before {
  content: "";
  position: absolute;
  inset: -20% -10% auto;
  height: 55vh;
  background:
