ProjectList rewrite:

```tsx
import type { Project } from "@/lib/projects";

type ProjectListProps = {
  projects: readonly Project[];
  headingId?: string;
  compact?: boolean;
};

function prettyUrl(url: string): string {
  try {
    const u = new URL(url);
    const path = u.pathname.replace(/\/$/, "");
    return `${u.host}${path === "/" ? "" : path}`;
  } catch {
    return url;
  }
}

export function ProjectList({ projects, headingId, compact = false }: ProjectListProps) {
  return (
    <ul className={`cv-list ${compact ? "mt-5" : "mt-8"}`} {...(headingId ? { "aria-labelledby": headingId } : {})}>
      {projects.map((project) => (
        <li key={project.name}>
          <a href={project.url} target="_blank" rel="noopener noreferrer" className="cv-row">
            <span className="flex min-w-0 flex-1 flex-col gap-x-3 gap-y-0.5 sm:flex-row sm:items-baseline">
              <span className="cv-row-name">{project.name}</span>
              <span className="cv-row-desc">{project.description}</span>
            </span>
            <span className="cv-row-meta">
              <span>{prettyUrl(project.url)} ↗</span>
              {project.year !== undefined ? <span>{project.year}</span> : null}
            </span>
          </a>
        </li>
      ))}
    </ul>
  );
}
```

compact prop now only affects mt — keep for API stability. Full vs compact desc size difference dropped (single row style). Fine — simpler.

Wait: description may be long; single-line truncate on sm+. OK.

Check projects data: year optional ✓. 

