/* Quiet status dot — ink pulse, functional not decorative. */
.status-dot {
  position: relative;
  display: inline-flex;
  border-radius: 9999px;
  background: currentColor;
}

.status-dot::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  background: currentColor;
  animation: ping-soft 2.4s var(--ease-out-quad) infinite;
}

@keyframes ping-soft {
  0% {
    transform: scale(1);
    opacity: 0.5;
  }
  70%,
  100% {
    transform: scale(2.8);
    opacity: 0;
  }
}

